#!/bin/sh
# Build an FFS root image for the QEMU Cayman machine from the NetBSD 3.1
# evbsh5 sets:
#   mkroot.sh <base.tgz> <etc.tgz> <tooldir> <output image> [size]
# The image holds /rescue, the full /etc set, device nodes generated by
# MAKEDEV, and the statically linked programs the rc scripts and a console
# login need.  Everything else in /bin and /sbin is a symlink into /rescue.
# Default size 32 MB (MEMORY_DISK_ROOT_SIZE=65536 in CAYMAN_QEMU).
set -e
BASE=$(realpath "$1"); ETC=$(realpath "$2"); TOOLS=$(realpath "$3")
OUT=$(realpath -m "$4"); SIZE=${5:-32m}
ROOT=$(mktemp -d)
cd "$ROOT"

tar --no-same-permissions -xzf "$ETC"
tar --no-same-permissions -xzf "$BASE" ./rescue ./var ./sbin/nologin \
	./usr/libexec/getty ./usr/bin/login \
	./usr/bin/sed ./usr/bin/awk ./usr/bin/grep ./usr/bin/egrep \
	./usr/bin/touch ./usr/bin/uname ./usr/bin/install ./usr/bin/logger \
	./usr/bin/tail ./usr/bin/head ./usr/bin/sort ./usr/bin/cut ./usr/bin/tr \
	./usr/bin/wc ./usr/bin/id ./usr/bin/env ./usr/bin/printf \
	./usr/bin/basename ./usr/bin/dirname ./usr/bin/cmp ./usr/bin/tset \
	./usr/bin/true ./usr/bin/false ./usr/bin/xargs ./usr/bin/find \
	./usr/bin/hexdump ./usr/bin/od ./usr/bin/uuencode ./usr/bin/uudecode ./usr/bin/du ./usr/bin/vmstat ./usr/bin/netstat \
	./usr/bin/top ./usr/bin/who ./usr/bin/w ./usr/bin/uptime ./usr/bin/less \
	./usr/bin/more \
	./usr/sbin/pwd_mkdb ./usr/sbin/dev_mkdb ./usr/sbin/syslogd \
	./usr/share/misc/termcap
chmod -R u+rwX .	# some set directories are unreadable to their owner

mkdir -p bin sbin usr/bin usr/sbin usr/libexec usr/share/misc tmp mnt kern \
	var/run var/log var/tmp var/db var/spool/lock var/mail
chmod 1777 tmp var/tmp

# Place the rescue programs where the real ones would live.
inbin=" cat chio chmod cp csh date dd df domainname echo ed expr hostname kill \
	ksh ln ls mkdir mt mv pax tar ps pwd rcmd rcp rm rmdir sh sleep stty \
	sync systrace test [ chgrp "
inusrbin=" bzip2 bunzip2 bzcat ftp gzip gunzip gzcat zcat kdump ktrace ktruss \
	ldd less more vi ex scp ssh slogin "
inusrsbin=" chroot installboot "
for f in rescue/*; do
	n=${f#rescue/}
	case "$inbin" in *" $n "*) d=bin ;; *)
	case "$inusrbin" in *" $n "*) d=usr/bin ;; *)
	case "$inusrsbin" in *" $n "*) d=usr/sbin ;; *) d=sbin ;; esac ;; esac ;; esac
	[ -e "$d/$n" ] || ln -s "$(echo "$d" | sed 's|[^/]*|..|g')/rescue/$n" "$d/$n"
done

# Device nodes: let MAKEDEV emit an mtree spec and feed it to makefs.
( cd dev && sh ./MAKEDEV -s std md0 pty0 ) | \
	sed -e 's|^\./\([^ ]\)|./dev/\1|' -e 's|^\. |./dev |' > "$ROOT.spec"
cat >> "$ROOT.spec" <<'SPEC'
./tmp type=dir mode=01777
./var type=dir
./var/tmp type=dir mode=01777
SPEC
sed -i '1i /set type=file uid=0 gid=0\n. type=dir' "$ROOT.spec"

cat >> etc/rc.conf <<'RC'
rc_configured=YES
hostname=cayman
ifconfig_sm0="inet 10.0.2.15 netmask 255.255.255.0"
defaultroute=10.0.2.2
savecore=NO quota=NO ldconfig=NO virecover=NO inetd=NO cron=NO
clear_tmp=NO fixsb=NO postfix=NO sendmail=NO
RC
cat > etc/fstab <<'FS'
/dev/md0a	/	ffs	rw	0 0
kernfs		/kern	kernfs	rw	0 0
FS
sed -i 's|^console.*|console	"/usr/libexec/getty std.38400"	vt100	on secure|' etc/ttys
echo "10.0.2.15	cayman" >> etc/hosts
echo cayman > etc/myname

"$TOOLS/bin/nbmakefs" -t ffs -s "$SIZE" -F "$ROOT.spec" -o density=4096 "$OUT" "$ROOT"
rm -rf "$ROOT" "$ROOT.spec"
